// The open findings of an image name the caller can read, counted per tag and severity: a finding counts for the tag whose manifest it
// names or whose index names that manifest (R-VULN-020).
func (q *Queries) VulnImageTagCounts(ctx context.Context, arg VulnImageTagCountsParams) ([]VulnImageTagCountsRow, error) {
	rows, err := q.db.Query(ctx, vulnImageTagCounts,
		arg.HasRepos,
		arg.Repos,
		arg.Whole,
		arg.Rows,
		arg.PackageRows,
		arg.Name,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VulnImageTagCountsRow{}
	for rows.Next() {
		var i VulnImageTagCountsRow
		if err := rows.Scan(&i.Version, &i.Severity, &i.N); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const vulnImageUpsertAdvisory = `-- name: VulnImageUpsertAdvisory :exec
INSERT INTO vuln_advisory (ecosystem, id, canonical_id, modified, published, kind, summary, details, severity, severity_source, cvss_version, cvss_vector,
                           cvss_score, "references", cwe_ids, record_sha256)
VALUES ('OCI', $1::text, $1::text, to_timestamp($2::bigint / 1000000.0),
        CASE WHEN $3::bigint = 0 THEN NULL ELSE to_timestamp($3::bigint / 1000000.0) END,
        'vulnerability', $4::text, $5::text, $6::text, $7::text,
        NULLIF($8::text, ''), NULLIF($9::text, ''), NULLIF($10::float8, -1)::numeric(3,1),
        $11::jsonb, $12::text[], $13)
ON CONFLICT (ecosystem, id) DO UPDATE
   SET modified = EXCLUDED.modified, published = EXCLUDED.published, summary = EXCLUDED.summary, details = EXCLUDED.details,
       severity = EXCLUDED.severity, severity_source = EXCLUDED.severity_source, cvss_version = EXCLUDED.cvss_version,
       cvss_vector = EXCLUDED.cvss_vector, cvss_score = EXCLUDED.cvss_score, "references" = EXCLUDED."references", cwe_ids = EXCLUDED.cwe_ids,
       record_sha256 = EXCLUDED.record_sha256
 WHERE vuln_advisory.record_sha256 <> EXCLUDED.record_sha256
`

type VulnImageUpsertAdvisoryParams struct {
	ID             string
	ModifiedUs     int64
	PublishedUs    int64
	Summary        string
	Details        string
	Severity       string
	SeveritySource string
	CvssVersion    string
	CvssVector     string
	CvssScore      float64
	Refs           json.RawMessage
	CweIds         []string
	RecordSha256   []byte
}

// The advisory of an image finding, as the analyser reported it: the findings API, the detail and the filters read the same table as
// for the package formats. No affected rows: nothing matches it by name.
func (q *Queries) VulnImageUpsertAdvisory(ctx context.Context, arg VulnImageUpsertAdvisoryParams) error {
	_, err := q.db.Exec(ctx, vulnImageUpsertAdvisory,
		arg.ID,
		arg.ModifiedUs,
		arg.PublishedUs,
		arg.Summary,
		arg.Details,
		arg.Severity,
		arg.SeveritySource,
		arg.CvssVersion,
		arg.CvssVector,
		arg.CvssScore,
		arg.Refs,
		arg.CweIds,
		arg.RecordSha256,
	)
	return err
}

const vulnImageVerdict = `-- name: VulnImageVerdict :one
SELECT COALESCE(blk.id::text, '')::text AS finding_id, COALESCE(blk.advisory_id, '')::text AS advisory_id,
       COALESCE(blk.kind, '')::text AS kind, COALESCE(blk.status, '')::text AS status, COALESCE(s.state, '')::text AS scan_state,
       (s.db_digest IS NOT NULL)::boolean AS detected
  FROM (SELECT 1) AS one
  LEFT JOIN vuln_image_scan s ON s.repo_id = $1::bigint AND s.name = $2::text AND s.digest = $3
  LEFT JOIN LATERAL (
        SELECT f.id, f.advisory_id, f.kind, f.status
          FROM vuln_finding f
         WHERE f.repo_id = $1::bigint AND f.ecosystem = 'OCI' AND f.package_name = $2::text
           AND f.version = $4::text
           AND f.status IN ('needs_triage', 'confirmed', 'blocked')
           AND (f.status = 'blocked' OR (f.kind = 'malicious' AND $5::boolean))
         ORDER BY (f.kind = 'malicious' AND $5::boolean) DESC, f.severity_rank DESC, f.advisory_id
         LIMIT 1) AS blk ON true
`

type VulnImageVerdictParams struct {
	RepoID         int64
	Name           string
	Digest         []byte
	Version        string
	BlockMalicious bool
}

type VulnImageVerdictRow struct {
	FindingID  string
	AdvisoryID string
	Kind       string
	Status     string
	ScanState  string
	Detected   bool
}

// What a pull of a manifest needs to know (R-VULN-015): the finding that blocks the manifest in the repository, if any, and how far the
// manifest has been scanned. One statement, the finding's unique index and the scan row's key.
func (q *Queries) VulnImageVerdict(ctx context.Context, arg VulnImageVerdictParams) (VulnImageVerdictRow, error) {
	row := q.db.QueryRow(ctx, vulnImageVerdict,
		arg.RepoID,
		arg.Name,
		arg.Digest,
		arg.Version,
		arg.BlockMalicious,
	)
	var i VulnImageVerdictRow
	err := row.Scan(
		&i.FindingID,
		&i.AdvisoryID,
		&i.Kind,
		&i.Status,
		&i.ScanState,
		&i.Detected,
	)
	return i, err
}
